body.script:
(async function () {
  var s = atob(document.getElementById("p").textContent.trim());
  var u = new Uint8Array(s.length);
  for (var i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
  var t = await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  var all = JSON.parse(t);
  window.__pages = all;
  var f = document.getElementById("x");
  f.srcdoc = all["index.html"];
  f.focus();
})();
